9	// resolveSSECreatorID returns the CreatorID used for SSE delivery filtering.
10	// For a comment memo, it returns the parent memo's CreatorID so that private
11	// parent-memo events are scoped to the parent owner.
12	func resolveSSECreatorID(memo *store.Memo, parentMemo *store.Memo) int32 {
13		if memo == nil {
14			return 0
15		}
16		if parentMemo != nil {
17			return parentMemo.CreatorID
18		}
19		return memo.CreatorID
20	}
